"""Summarize node sequence gaps without changing node files."""
import json
import os
import re
import sys
from collections import Counter
from pathlib import Path


def _reject_constant(value):
    raise ValueError(value)


def _read_json(raw):
    return json.loads(raw.decode("utf-8"), parse_constant=_reject_constant)


def _names(folder, channel):
    pattern = re.compile(re.escape(channel) + r"\.([0-9]{12})\.jsonl")
    numbered = []
    active = None
    with os.scandir(folder) as entries:
        for entry in entries:
            if not entry.is_file(follow_symlinks=False):
                continue
            match = pattern.fullmatch(entry.name)
            if match:
                numbered.append((int(match.group(1)), entry.name))
            elif entry.name == channel + ".active.jsonl":
                active = entry.name
    return [name for _, name in sorted(numbered)] + ([active] if active else [])


def _records(folder, name, bad):
    parts = (folder / name).read_bytes().split(b"\n")
    for line_number, raw in enumerate(parts[:-1], 1):
        try:
            record = _read_json(raw)
        except (ValueError, UnicodeError):
            bad.append({"file": name, "line": line_number, "why": "bad_json"})
            continue
        if not isinstance(record, dict) or type(record.get("seq")) is not int or record["seq"] < 1:
            bad.append({"file": name, "line": line_number, "why": "no_seq"})
            continue
        yield record["seq"]
    if parts[-1]:
        bad.append({"file": name, "line": len(parts), "why": "torn"})


def _state(folder):
    try:
        raw = (folder / "state.json").read_bytes()
    except FileNotFoundError:
        return None, False
    except OSError:
        return None, True
    try:
        value = _read_json(raw)
    except (ValueError, UnicodeError):
        return None, True
    if not isinstance(value, dict) or not isinstance(value.get("channels"), dict):
        return None, True
    return value["channels"], False


def summarize(folder):
    channels = {}
    bad = []
    state, bad_state = _state(folder)
    for channel in ("obs", "must"):
        counts = Counter(seq for name in _names(folder, channel)
                         for seq in _records(folder, name, bad))
        seqs = sorted(counts)
        first = seqs[0] if seqs else None
        last = seqs[-1] if seqs else None
        next_seq = unacked = stale_next = None
        if state is not None:
            fields = state.get(channel)
            if (not isinstance(fields, dict)
                    or type(fields.get("next_seq")) is not int
                    or (channel == "must" and type(fields.get("acked_upto")) is not int)):
                bad_state = True
            else:
                next_seq = fields["next_seq"]
                if channel == "must":
                    unacked = sum(seq > fields["acked_upto"] for seq in seqs)
                if last is not None:
                    stale_next = next_seq != last + 1
        channels[channel] = {
            "count": sum(counts.values()), "first": first, "last": last,
            "missing": [[a + 1, b - 1] for a, b in zip(seqs, seqs[1:]) if b > a + 1],
            "dup": [seq for seq in seqs if counts[seq] >= 2],
            "next_seq": next_seq, "unacked": unacked, "stale_next": stale_next,
        }
    if bad_state:
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
    bad.sort(key=lambda item: (item["file"], 0 if item["line"] is None else item["line"], item["why"]))
    return {"v": 1, "channels": channels, "bad": bad}


def main(argv=None):
    args = sys.argv[1:] if argv is None else argv
    if len(args) != 1 or not Path(args[0]).is_dir():
        return 2
    print(json.dumps(summarize(Path(args[0])), ensure_ascii=False, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
